-- taxonomy_nature_forme_manifest_20260724.sql
-- Frozen from the cloud corpus on 2026-07-24 after explicit PO approval.
-- Source of truth for migration_taxonomy_nature_forme.sql; no heuristic runs in production.
-- 243 unique objects = 199 published automatic + 1 archived technical carrier
-- + 40 named PO decisions + 3 PO-4 structural folds.

CREATE TEMP TABLE IF NOT EXISTS _taxonomy_nature_forme_manifest (
  object_id TEXT PRIMARY KEY,
  expected_old_code TEXT NOT NULL,
  target_code TEXT NOT NULL,
  source TEXT NOT NULL,
  motif TEXT NOT NULL,
  CONSTRAINT chk_taxonomy_nature_forme_manifest_source
    CHECK (source IN (
      'taxonomy_nature_forme_20260724',
      'taxonomy_nature_forme_arbitrage_20260724'
    ))
) ON COMMIT DROP;

TRUNCATE _taxonomy_nature_forme_manifest;


DO $manifest$
DECLARE
  v_total INTEGER;
  v_auto INTEGER;
  v_po INTEGER;
  v_legacy INTEGER;
BEGIN
  SELECT count(*),
         count(*) FILTER (WHERE source = 'taxonomy_nature_forme_20260724'),
         count(*) FILTER (WHERE source = 'taxonomy_nature_forme_arbitrage_20260724'),
         count(*) FILTER (WHERE expected_old_code IN ('gite_villa', 'bungalow_chalet'))
  INTO v_total, v_auto, v_po, v_legacy
  FROM _taxonomy_nature_forme_manifest;

  IF (v_total, v_auto, v_po, v_legacy) IS DISTINCT FROM (243, 200, 43, 231) THEN
    RAISE EXCEPTION
      'taxonomy nature/forme manifest mismatch: total=%, auto=%, po=%, legacy=% (expected 243/200/43/231)',
      v_total, v_auto, v_po, v_legacy;
  END IF;
END
$manifest$;
